ROUTINE_DEFINITION:
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE v_riderId VARCHAR(20);
    DECLARE v_totalRiders INT;
    DECLARE v_companyTotalAmount DECIMAL(10,2) DEFAULT 0;
    DECLARE v_ridersProcessed INT DEFAULT 0;
    DECLARE v_ridersSkipped INT DEFAULT 0;

    DECLARE v_payrollId INT;
    DECLARE v_netPay DECIMAL(10,2);
    DECLARE v_success TINYINT;
    DECLARE v_errorMessage TEXT;

    DECLARE rider_cursor CURSOR FOR
        WITH latest_crc AS (
            SELECT
                crc.clientUserId,
                cui.clientId,
                crc.riderId,
                cui.riderId AS permanentRiderId,
                ROW_NUMBER() OVER (
                    PARTITION BY crc.riderId
                    ORDER BY crc.startDate DESC
                ) AS rn
            FROM ClientRiderConfig crc
            INNER JOIN ClientUserId cui ON crc.clientUserId = cui.clientUserId
            WHERE (
                (crc.endDate IS NULL AND crc.startDate <= LAST_DAY(p_payMonth))
                OR (
                    crc.endDate >= p_payMonth
                    AND crc.endDate <= LAST_DAY(p_payMonth)
                )
            )
        ),
        all_riders AS (
            SELECT
                clientId,
                clientUserId,
                riderId,
                0 AS isFullTime
            FROM latest_crc
            WHERE rn = 1

            UNION ALL

            SELECT
                clientId,
                clientUserId,
                permanentRiderId AS riderId,
                1 AS isFullTime
            FROM latest_crc
            WHERE rn = 1
                AND permanentRiderId IS NOT NULL
        )
        SELECT ar.riderId
        FROM all_riders ar
        INNER JOIN Rider r ON ar.riderId = r.riderId
        INNER JOIN Company c ON c.companyId = r.companyId
        WHERE r.isActive = 1
        	AND c.companyId = p_companyId
            AND (
                p_retryFailedRiders = 0
                OR EXISTS (
                    SELECT 1
                    FROM PayrollErrorLog prl
                    WHERE prl.riderId = r.riderId
                        AND prl.companyId = r.companyId
                        AND prl.payMonth = p_payMonth
                )
            )
        GROUP BY ar.riderId;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    /* ================= INITIALIZATION ================= */
    SET @companyId := p_companyId;
    SET @payMonth := DATE_FORMAT(p_payMonth, '%Y-%m-01');
    SET @retryFailed := p_retryFailedRiders;
    SET @createdBy := p_createdBy;
    SET p_result = 0;

    START TRANSACTION;

    /* ================= SUMMARY INITIALIZATION ================= */
    INSERT INTO CompanyPayrollSummary (
        companyId,
        payMonth,
        status,
        createdBy,
        createdAt
    )
    VALUES (
        @companyId,
        @payMonth,
        'PROCESSING',
        @createdBy,
        NOW()
    )
    ON DUPLICATE KEY UPDATE
        status = 'PROCESSING',
        updatedAt = NOW(),
        updatedBy = @createdBy;

    COMMIT;

    OPEN rider_cursor;

    /* ================= RIDER PROCESSING LOOP ================= */
    rider_loop: LOOP
        FETCH rider_cursor INTO v_riderId;

        IF done = 1 THEN
            LEAVE rider_loop;
        END IF;

        CALL sp_process_rider_payroll(
            v_riderId,
            @companyId,
            @payMonth,
            @createdBy,
            v_payrollId,
            v_netPay,
            v_success,
            v_errorMessage
        );

        IF v_success = 1 THEN
            SET v_ridersProcessed = v_ridersProcessed + 1;
            SET v_companyTotalAmount = v_companyTotalAmount + IFNULL(v_netPay, 0);
        ELSE
            SET v_ridersSkipped = v_ridersSkipped + 1;
        END IF;

    END LOOP;

    CLOSE rider_cursor;

    /* ================= SUMMARY FINALIZATION ================= */
    START TRANSACTION;

    UPDATE CompanyPayrollSummary
    SET
        ridersProcessed = IFNULL(ridersProcessed, 0) + v_ridersProcessed,
        ridersSkipped = v_ridersSkipped,
        totalPayableAmount = IFNULL(totalPayableAmount, 0) + v_companyTotalAmount,
        status = CASE
            WHEN v_ridersSkipped = 0 THEN 'COMPLETED'
            ELSE 'PARTIALLY_DONE'
        END,
        updatedAt = NOW(),
        updatedBy = @createdBy
    WHERE companyId = @companyId
        AND payMonth = @payMonth;

    COMMIT;

    SET p_result = 1;

END
